"use client";
import { cn } from "@/lib/utils";
import { useRef, useState } from "react";
import { Volume2, VolumeX } from "lucide-react";
import { panel } from "@/lib/takt-surface";
export function WaveSlider({
  className,
  label = "Громкость",
  defaultValue = 60,
  value,
  onValueChange,
}: {
  className?: string;
  label?: string;
  defaultValue?: number;
  value?: number;
  onValueChange?: (value: number) => void;
}) {
  const [internal, setInternal] = useState(defaultValue);
  const level = Math.max(0, Math.min(100, value ?? internal));
  const remembered = useRef(level || 60);
  function setVolume(n: number) {
    if (value === undefined) setInternal(n);
    onValueChange?.(n);
  }
  return (
    <div
      className={cn(
        panel +
          " flex w-60 max-w-full items-center gap-2.5 rounded-full! px-2.5! py-1!",
        className,
      )}
    >
      <span className="flex shrink-0 items-center text-xs font-medium">
        <button
          type="button"
          aria-label={level === 0 ? "Включить звук" : "Выключить звук"}
          aria-pressed={level === 0}
          className="grid size-9 place-items-center rounded-full bg-muted"
          onClick={() => {
            if (level) {
              remembered.current = level;
              setVolume(0);
            } else setVolume(remembered.current);
          }}
        >
          {level === 0 ? <VolumeX size={15} /> : <Volume2 size={15} />}
        </button>
      </span>
      <span className="relative flex h-11 min-w-0 flex-1 items-center rounded focus-within:ring-1 focus-within:ring-foreground/35">
        <span
          aria-hidden
          className="relative mx-1 h-1 w-full rounded-full bg-foreground/15"
        >
          <i
            className="absolute inset-y-0 left-0 rounded-full bg-primary"
            style={{ width: level + "%" }}
          />
          <i
            className="absolute top-1/2 size-3 -translate-1/2 rounded-full bg-primary"
            style={{ left: level + "%" }}
          />
        </span>
        <input
          type="range"
          aria-label={label}
          aria-valuetext={level + "%"}
          value={level}
          className="absolute inset-0 h-full w-full cursor-ew-resize opacity-0"
          onChange={(e) => {
            const n = +e.target.value;
            setVolume(n);
          }}
        />
      </span>
      <output className="w-9 text-right font-mono text-xs tabular-nums">
        {level}%
      </output>
    </div>
  );
}

// Semantic shadcn colors keep the surfaces usable in a host project's own theme.
export const panel =
  "rounded-2xl border border-foreground/10 bg-card p-4 text-sm text-card-foreground shadow-[0_2px_5px_#0000000a,0_8px_18px_-12px_#0003]";
export const field =
  "min-h-10 min-w-0 w-full rounded-xl border border-foreground/10 bg-muted/70 px-3 text-sm text-foreground outline-none motion-safe:transition-[background-color,box-shadow] focus:bg-background focus:ring-1 focus:ring-foreground/35";
export const action =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-xl border border-foreground/10 bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground shadow-sm outline-offset-4 motion-safe:transition-[transform,box-shadow] motion-safe:active:translate-y-px motion-safe:active:scale-[.97] disabled:cursor-default disabled:opacity-50";
export const secondary =
  "inline-flex min-h-9 cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-foreground/10 bg-background px-3 text-xs font-medium text-foreground outline-offset-2 hover:bg-muted motion-safe:transition-[transform,background-color] motion-safe:active:scale-[.96] disabled:cursor-default disabled:opacity-45";
